<style>
.contact-form {
  max-width: 600px;
  margin: 0 auto;
  font-family: Arial, sans-serif;
}

.form-group {
  margin-bottom: 20px;
}

label {
  font-weight: bold;
  display: block;
  margin-bottom: 8px;
}

.required {
  color: red;
}

.name-fields {
  display: flex;
  gap: 10px;
}

.name-fields input {
  flex: 1;
}

input,
textarea {
  width: 100%;
  padding: 10px;
  box-sizing: border-box;
  border: 1px solid #ccc;
  border-radius: 4px;
}

.submit-btn {
  background-color: #2b6cb0;
  color: white;
  padding: 10px 20px;
  border: none;
  border-radius: 4px;
  font-size: 16px;
  cursor: pointer;
}

.submit-btn:hover {
  background-color: #2c5282;
}
</style>"},"elements":[],"widgetType":"html"}],"isInner":true},{"id":"d96854b","elType":"container","settings":{"flex_direction":"column","content_width":"full","width":{"unit":"%","size":"50"},"padding":{"unit":"px","top":"0","right":"0","bottom":"0","left":"50","isLinked":false}},"elements":[{"id":"d41587a","elType":"widget","settings":{"title":"We are always open <br>24/7 for you. ","header_size":"h3","typography_typography":"custom","typography_font_family":"Montserrat","typography_font_size":{"unit":"px","size":36,"sizes":[]},"typography_font_weight":"600","typography_line_height":{"unit":"px","size":46,"sizes":[]},"title_color":"#000000"},"elements":[],"widgetType":"heading"},{"id":"e1a36aa","elType":"widget","settings":{"editor":"<div class="wp-block-qubely-heading qubely-block-edd39e">
